head.script:
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};

scwin.__hasClass = function(className) {
	if (((j) => j.length ? j : $('#mf_widgetContainer1_widget0'))($('#widgetContainer1_widget0')).hasClass(className)) {
		return true;
	}
	return false;
};

scwin.checkVal = function() {
	return scwin.__getObj('widgetContainer1_widget0_title_text').innerText == 'widget0';
};

scwin.onpageload2 = function() {
	widgetContainer1.addWidgets({
		title: "widget0",
		src: null,
		scope: true,
		x: "0",
		y: 0,
		unitWidth: "03",
		unitHeight: 1,
		fixed: true,
		minimizeonfixed: true,
		maxmizeonfixed: true,
		maximizeonfixed: true
	});
	widgetContainer1.addWidgets({
		title: "widget1",
		src: null,
		scope: true,
		x: 0,
		y: 1,
		unitWidth: 4,
		unitHeight: 1
	});
	widgetContainer1.addWidgets({
		title: "widget2",
		src: null,
		scope: true,
		x: 0,
		y: 2,
		unitWidth: 4,
		unitHeight: 1
	});
};
